const raw = $input.first().json || {};
const b = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const clean = (v, max) => typeof v === 'string' ? v.replace(/[\u0000-\u001F\u007F]/g, ' ').trim().slice(0, max) : '';
const full_name = clean(b.full_name, 120);
const phone = clean(b.phone, 40);
const email = clean(b.email, 160).toLowerCase();
const dealership = clean(b.dealership, 160);
const stock_size = clean(b.stock_size, 40);
const message = clean(b.message, 1500);
const submission_id = clean(b.submission_id, 80);
if (!full_name) { throw new Error('SITE_ENQUIRY_REJECTED: no name was supplied, so there is nobody to notify about.'); }
if (!phone && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) { throw new Error('SITE_ENQUIRY_REJECTED: neither a phone number nor a valid email was supplied, so this enquiry cannot be answered.'); }
const subject = 'NEXUS enquiry - ' + full_name + (dealership ? ' | ' + dealership : '');
const lines = ['New NEXUS enquiry', '', 'Name:       ' + full_name, 'Dealership: ' + (dealership || '(not given)'), 'WhatsApp:   ' + (phone || '(not given)'), 'Email:      ' + (email || '(not given)'), 'Stock:      ' + (stock_size || '(not given)'), '', message || '(no message)', '', '--', 'submission ' + (submission_id || '(none sent)') + ' at ' + new Date().toISOString(), 'This is a NEXUS prospect, not a dealership customer. Nothing was written to any dealership record.'];
return [{ json: { subject, text: lines.join('\n'), reply_to: email || undefined, submission_id: submission_id || null } }];
